package dk.ek.gruppe_i.llm_project.service;

import dk.ek.gruppe_i.llm_project.housing.BaselineParameters;
import org.junit.jupiter.api.Test;
import org.springframework.core.io.ClassPathResource;
import org.springframework.util.StreamUtils;

import java.nio.charset.StandardCharsets;
import java.util.Properties;

import static org.junit.jupiter.api.Assertions.assertTrue;

/** The files generated by housing_eda.ipynb must be in src/main/resources/rag, and have the expected shape. */
class HousingResourcesTest {

    @Test
    void baselineParametersFileIsComplete() throws Exception {
        Properties properties = new Properties();
        try (var in = new ClassPathResource("rag/baseline-parameters.properties").getInputStream()) {
            properties.load(in);
        }
        BaselineParameters.fromProperties(properties); // throws if a value is missing or inconsistent
    }

    @Test
    void apartmentRulesHaveOneRulePerSituation() throws Exception {
        String text = StreamUtils.copyToString(new ClassPathResource("rag/apartment-rules.md").getInputStream(), StandardCharsets.UTF_8);
        long rules = HousingKnowledgeBase.split(text).stream().filter(chunk -> chunk.startsWith("## Rule ")).count();
        assertTrue(rules >= 6, "expected rules A-F, found " + rules);
    }

    @Test
    void otherApartmentFilesExist() throws Exception {
        for (String name : new String[]{"apartment-reference.md", "apartment-profile.md", "apartment-examples.md"}) {
            String text = StreamUtils.copyToString(new ClassPathResource("rag/" + name).getInputStream(), StandardCharsets.UTF_8);
            assertTrue(!HousingKnowledgeBase.split(text).isEmpty(), name);
        }
    }
}
